const API_BASE_URL=window.FORGEX_API_URL||"http://localhost:3000/api";async function getAuthHeaders(e){return e?{Authorization:`Bearer ${await e.getIdToken()}`}:{}}async function request(e,t={}){const{user:o,headers:s={},body:r,...i}=t,n=await getAuthHeaders(o),a=await fetch(`${API_BASE_URL}${e}`,{...i,headers:{"Content-Type":"application/json",...n,...s},body:r?JSON.stringify(r):void 0}),u=await a.json().catch(()=>({}));if(!a.ok)throw new Error(u.message||"Az API-kérés sikertelen.");return u}export const api={getReviews:()=>request("/reviews"),createReview:(e,t)=>request("/reviews",{method:"POST",user:e,body:t}),deleteReview:(e,t)=>request(`/reviews/${t}`,{method:"DELETE",user:e}),getBookings:e=>request("/bookings",{user:e}),createBooking:(e,t)=>request("/bookings",{method:"POST",user:e,body:t}),deleteBooking:(e,t)=>request(`/bookings/${t}`,{method:"DELETE",user:e})};